'use client'
import { cn, createMachine, useMachine, useSignals } from '@cascivo/core'
import type { HTMLAttributes } from 'react'
import styles from './avatar.module.css'

const machine = createMachine({
  initial: 'loading' as const,
  states: {
    loading: { on: { LOADED: 'loaded', ERROR: 'error' } },
    loaded: {},
    error: {},
  },
})

export interface AvatarProps extends HTMLAttributes<HTMLSpanElement> {
  src?: string
  /**
   * Alternative text describing the image.
   *
   * @defaultValue ``
   * @see the component manifest
   */
  alt?: string
  /** Full name — used to derive initials for the fallback and as the accessible label. */
  name?: string
  /** Explicit fallback text (initials/glyph). Overrides initials derived from `name`. */
  fallback?: string
  size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl'
  status?: 'online' | 'offline' | 'busy'
}

export function Avatar({
  src,
  alt = '',
  name,
  fallback,
  size = 'md',
  status,
  className,
  ...props
}: AvatarProps) {
  useSignals()
  const [state, send] = useMachine(machine)
  const showImage = Boolean(src) && state.value !== 'error'
  // Explicit `fallback` wins; otherwise derive initials from `name`.
  const fallbackText = fallback ?? initialsFrom(name)
  // Only expose role="img" when there's a name for it. A nameless avatar (no
  // alt, no name, no fallback — e.g. a src that 404s in a static build) becomes
  // decorative instead of an unlabeled image (role-img-alt).
  const label = alt || name || fallback

  return (
    <span
      data-size={size}
      data-status={status}
      className={cn(styles['avatar'], className)}
      role={showImage || !label ? undefined : 'img'}
      aria-label={showImage ? undefined : label || undefined}
      {...props}
    >
      {showImage ? (
        <img
          className={styles['image']}
          src={src}
          alt={alt || name || ''}
          onLoad={() => send('LOADED')}
          onError={() => send('ERROR')}
        />
      ) : (
        <span className={styles['fallback']} aria-hidden="true">
          {fallbackText}
        </span>
      )}
      {status && <span className={styles['status']} aria-hidden="true" />}
    </span>
  )
}

/** First grapheme of the first word + first of the last word, uppercased. */
function initialsFrom(name?: string): string | undefined {
  if (!name) return undefined
  const words = name.trim().split(/\s+/).filter(Boolean)
  if (words.length === 0) return undefined
  const first = firstGrapheme(words[0]!)
  const last = words.length > 1 ? firstGrapheme(words[words.length - 1]!) : ''
  const initials = (first + last).toLocaleUpperCase()
  return initials || undefined
}

function firstGrapheme(word: string): string {
  if (typeof Intl !== 'undefined' && 'Segmenter' in Intl) {
    const seg = new Intl.Segmenter(undefined, { granularity: 'grapheme' })
    for (const s of seg.segment(word)) return s.segment
  }
  return [...word][0] ?? ''
}

@layer cascivo.component {
  .avatar {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    overflow: visible;
    border-radius: var(--cascivo-radius-full);
    background-color: var(--cascivo-color-accent-subtle);
    color: var(--cascivo-color-text);
    font-family: var(--cascivo-font-sans);
    font-weight: var(--cascivo-font-medium);
    user-select: none;

    &[data-size='xs'] {
      inline-size: 1.5rem;
      block-size: 1.5rem;
      font-size: var(--cascivo-text-xs);
    }
    &[data-size='sm'] {
      inline-size: 2rem;
      block-size: 2rem;
      font-size: var(--cascivo-text-xs);
    }
    &[data-size='md'] {
      inline-size: 2.5rem;
      block-size: 2.5rem;
      font-size: var(--cascivo-text-sm);
    }
    &[data-size='lg'] {
      inline-size: 3rem;
      block-size: 3rem;
      font-size: var(--cascivo-text-base);
    }
    &[data-size='xl'] {
      inline-size: 4rem;
      block-size: 4rem;
      font-size: var(--cascivo-text-lg);
    }
  }

  .image {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
    border-radius: inherit;
  }

  .fallback {
    line-height: 1;
    text-transform: uppercase;
  }

  .status {
    position: absolute;
    inset-block-end: 0;
    inset-inline-end: 0;
    inline-size: 28%;
    block-size: 28%;
    min-inline-size: 0.5rem;
    min-block-size: 0.5rem;
    border-radius: var(--cascivo-radius-full);
    border: 2px solid var(--cascivo-color-surface);

    .avatar[data-status='online'] & {
      background-color: var(--cascivo-color-success);
    }
    .avatar[data-status='offline'] & {
      background-color: var(--cascivo-color-text-muted);
    }
    .avatar[data-status='busy'] & {
      background-color: var(--cascivo-color-destructive);
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Avatar',
  description: 'Displays a user image with initials fallback',
  category: 'display',
  // The <img> (or initials fallback) is in the server HTML; the machine only swaps in the
  // fallback after a load error.
  clientJs: 'enhancement',
  states: ['loading', 'loaded', 'error'],
  variants: [],
  sizes: ['xs', 'sm', 'md', 'lg', 'xl'],
  props: [
    { name: 'src', description: 'Image source URL.', type: 'string', required: false },
    {
      name: 'alt',
      default: '',
      description: 'Alternative text describing the image.',
      type: 'string',
      required: false,
    },
    {
      name: 'name',
      type: 'string',
      required: false,
      description:
        'Full name — used to derive initials for the fallback and as the accessible label.',
    },
    {
      name: 'fallback',
      type: 'string',
      required: false,
      description: 'Explicit fallback text (initials/glyph); overrides initials derived from name.',
    },
    {
      name: 'size',
      description: "Visual size of the component (e.g. 'sm', 'md', 'lg').",
      type: "'xs' | 'sm' | 'md' | 'lg' | 'xl'",
      required: false,
      default: 'md',
    },
    {
      name: 'status',
      description: 'Status state.',
      type: "'online' | 'offline' | 'busy'",
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-accent-subtle',
    '--cascivo-color-success',
    '--cascivo-color-destructive',
    '--cascivo-radius-full',
  ],
  accessibility: {
    role: 'img',
    wcag: '2.2-AA',
    keyboard: [],
  },
  examples: [
    { title: 'Image', code: '<Avatar src="/jane.jpg" alt="Jane Doe" />' },
    {
      title: 'Initials from name',
      code: '<Avatar name="Ada Lovelace" /> // renders "AL"',
      description: 'Derives initials automatically; also sets the accessible label.',
    },
    { title: 'Explicit fallback', code: '<Avatar fallback="JD" alt="Jane Doe" />' },
    { title: 'With status', code: '<Avatar name="Jane Doe" status="online" />' },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['user', 'profile', 'image'],
  intent: {
    whenToUse: [
      'Representing a person or entity with a thumbnail image and initials fallback',
      'Showing presence/status alongside an identity (status prop)',
      'Compactly identifying authors in lists, comments, and headers',
    ],
    whenNotToUse: [
      'Decorative imagery unrelated to identity — use a plain <img>',
      'A generic icon or logo with no person/entity meaning',
    ],
    antiPatterns: [
      {
        bad: '<Avatar src="/logo.png" /> with no alt and no fallback',
        good: '<Avatar src="/jane.jpg" alt="Jane Doe" fallback="JD" />',
        why: 'Without alt/fallback the identity is invisible to assistive tech and breaks on image load failure',
      },
    ],
    related: [
      {
        name: 'Status',
        relationship: 'alternative',
        reason: 'Use Status for a standalone state dot not attached to an identity',
      },
    ],
    a11yRationale:
      'role="img" with alt names the person; on image error it falls back to initials so the identity survives; the status dot carries an accessible label rather than relying on color alone',
    flexibility: [
      {
        area: 'size',
        level: 'flexible',
        note: 'Pick the size that fits the surrounding density',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Fallback and status colors must resolve to --cascivo-* semantic tokens',
      },
    ],
  },
}
